            value = a[i];
            for (j = i - 1; j >= 0 && value > a[j]; --j) {
                a[j + 1] = a[j];
                idx[j + 1] = idx[j];
            }
            a[j + 1] = value;
            idx[j + 1] = i++;
        }
        for (i = K; i < L; ++i) {
            value = a[i];
            if (value <= a[K - 1]) continue;
