package com.github.tartaricacid.touhoulittlemaid.libs.gagravarr.flac;

import com.github.tartaricacid.touhoulittlemaid.libs.gagravarr.flac.FlacOggInfo;
import com.github.tartaricacid.touhoulittlemaid.libs.gagravarr.ogg.HighLevelOggStreamPacket;
import com.github.tartaricacid.touhoulittlemaid.libs.gagravarr.ogg.IOUtils;
import com.github.tartaricacid.touhoulittlemaid.libs.gagravarr.ogg.OggPacket;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

public class FlacFirstOggPacket
extends HighLevelOggStreamPacket {
    private int majorVersion;
    private int minorVersion;
    private int numberOfHeaderBlocks;
    private FlacOggInfo info;

    public FlacFirstOggPacket() {
        this(new FlacOggInfo());
    }

    public FlacFirstOggPacket(FlacOggInfo info) {
        this.majorVersion = 1;
        this.minorVersion = 0;
        this.numberOfHeaderBlocks = 0;
        this.info = info;
        this.info.setFlacFirstOggPacket(this);
    }

    public FlacFirstOggPacket(OggPacket oggPacket) {
        super(oggPacket);
        byte[] data = this.getData();
        this.majorVersion = IOUtils.toInt(data[5]);
        this.minorVersion = IOUtils.toInt(data[6]);
        this.numberOfHeaderBlocks = IOUtils.getInt2BE(data, 7);
        this.info = new FlacOggInfo(data, 17, this);
    }

    public OggPacket write() {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try {
            baos.write("FLAC".getBytes("ASCII"));
            baos.write(this.majorVersion);
            baos.write(this.minorVersion);
            IOUtils.writeInt2BE(baos, this.numberOfHeaderBlocks);
            baos.write("fLaC".getBytes("ASCII"));
            baos.write(this.info.getData());
        }
        catch (IOException e) {
            throw new RuntimeException(e);
        }
        this.setData(baos.toByteArray());
        return super.write();
    }

    public int getMajorVersion() {
        return this.majorVersion;
    }

    public void setMajorVersion(int majorVersion) {
        if (majorVersion > 255) {
            throw new IllegalArgumentException("Version numbers must be in the range 0-255");
        }
        this.majorVersion = majorVersion;
    }

    public FlacOggInfo getInfo() {
        return this.info;
    }

    public int getMinorVersion() {
        return this.minorVersion;
    }

    public void setMinorVersion(int minorVersion) {
        if (minorVersion > 255) {
            throw new IllegalArgumentException("Version numbers must be in the range 0-255");
        }
        this.minorVersion = minorVersion;
    }

    public int getNumberOfHeaderBlocks() {
        return this.numberOfHeaderBlocks;
    }

    public void setNumberOfHeaderBlocks(int numberOfHeaderBlocks) {
        this.numberOfHeaderBlocks = numberOfHeaderBlocks;
    }

    public static boolean isFlacStream(OggPacket firstPacket) {
        if (!firstPacket.isBeginningOfStream()) {
            return false;
        }
        return FlacFirstOggPacket.isFlacSpecial(firstPacket);
    }

